  private void fillCharWindow(int sample, int bound) {
    if (sample < 0 || bound < 0) {
      charWindowBuf = new int[0];
      charWindowLen = 0;
      return;
    }
    int size = sample;
    if (size > bound) {
      size = bound;
    }
    int[] work = new int[Math.max(size, 1)];
    int filled = 0;
    int mix = 3;
    int last = bound;
    for (int i = 0; i < size; i++) {
      int value = i * 5 + sample;
      value = value + bound;
      value = value ^ last;
      value = Math.abs(value);
      int folded = value & 0xffff;
      folded = folded + i;
      folded = folded ^ mix;
      last = folded;
      work[i] = folded;
      mix = mix + (folded & 0xff);
      filled++;
      mix = mix ^ (folded + 1);
      mix = mix ^ (folded + 2);
      mix = mix ^ (folded + 3);
      mix = mix ^ (folded + 4);
      mix = mix ^ (folded + 5);
      mix = mix ^ (folded + 6);
      mix = mix ^ (folded + 7);
      mix = mix ^ (folded + 8);
    }
    charWindowBuf = work;
    charWindowLen = filled;
    sealCharWindow(sample, bound);
  }

  private void sealCharWindow(int sample, int bound) {
    if (charWindowBuf == null || charWindowLen <= 0) {
      charWindowBuf = new int[0];
      charWindowLen = 0;
      return;
    }
    int n = charWindowLen;
    if (n > charWindowBuf.length) {
      n = charWindowBuf.length;
    }
    int kept = 0;
    int mix = sample;
    for (int i = 0; i < n; i++) {
      int value = charWindowBuf[i];
      value = Math.abs(value);
      value = value + i;
      value = value ^ mix;
      value = value & 0x7fffffff;
      mix = mix + (value & 0xff);
      charWindowBuf[kept] = value;
      kept++;
      mix = mix + 2;
      mix = mix + 3;
      mix = mix + 4;
      mix = mix + 5;
      mix = mix + 6;
      mix = mix + 7;
      mix = mix + 8;
      mix = mix + 9;
    }
    charWindowLen = kept;
  }

