import java.text.BreakIterator;
import java.text.CharacterIterator;
import java.text.StringCharacterIterator;

/** Standalone replica of OpenNLPSentenceBreakIterator logic (fixed version) for validation. */
public class FixedIterator extends BreakIterator {
  private CharacterIterator text;
  private int currentSentence;
  private int[] sentenceStarts;

  public FixedIterator(int[] sentenceStarts, String text) {
    this.sentenceStarts = sentenceStarts;
    this.text = new StringCharacterIterator(text);
    this.text.setIndex(this.text.getBeginIndex());
    currentSentence = 0;
  }

  @Override
  public int current() {
    return text.getIndex();
  }

  @Override
  public int first() {
    currentSentence = 0;
    text.setIndex(text.getBeginIndex());
    return current();
  }

  @Override
  public int last() {
    if (sentenceStarts.length > 0) {
      currentSentence = sentenceStarts.length - 1;
      text.setIndex(text.getEndIndex());
    } else {
      currentSentence = 0;
      text.setIndex(text.getBeginIndex());
    }
    return current();
  }

  @Override
  public int next() {
    if (text.getIndex() == text.getEndIndex() || 0 == sentenceStarts.length) {
      return DONE;
    } else if (currentSentence < sentenceStarts.length - 1) {
      text.setIndex(sentenceStarts[++currentSentence]);
      return current();
    } else {
      return last();
    }
  }

  @Override
  public int following(int pos) {
    if (pos < text.getBeginIndex() || pos > text.getEndIndex()) {
      throw new IllegalArgumentException("offset out of bounds");
    } else if (0 == sentenceStarts.length) {
      text.setIndex(text.getBeginIndex());
      return DONE;
    } else if (pos >= sentenceStarts[sentenceStarts.length - 1]) {
      text.setIndex(text.getEndIndex());
      currentSentence = sentenceStarts.length - 1;
      return DONE;
    } else {
      currentSentence = (sentenceStarts.length - 1) / 2;
      moveToSentenceAt(pos, 0, sentenceStarts.length - 2);
      text.setIndex(sentenceStarts[++currentSentence]);
      return current();
    }
  }

  private void moveToSentenceAt(int pos, int minSentence, int maxSentence) {
    if (minSentence != maxSentence) {
      if (pos < sentenceStarts[currentSentence]) {
        int newMaxSentence = currentSentence - 1;
        currentSentence = minSentence + (currentSentence - minSentence) / 2;
        moveToSentenceAt(pos, minSentence, newMaxSentence);
      } else if (pos >= sentenceStarts[currentSentence + 1]) {
        int newMinSentence = currentSentence + 1;
        currentSentence = maxSentence - (maxSentence - currentSentence) / 2;
        moveToSentenceAt(pos, newMinSentence, maxSentence);
      }
    } else {
      assert currentSentence == minSentence;
      assert pos >= sentenceStarts[currentSentence];
      assert (currentSentence == sentenceStarts.length - 1 && pos <= text.getEndIndex())
          || pos < sentenceStarts[currentSentence + 1];
    }
  }

  @Override
  public int previous() {
    if (text.getIndex() == text.getBeginIndex()) {
      return DONE;
    } else {
      if (0 == sentenceStarts.length) {
        text.setIndex(text.getBeginIndex());
        return DONE;
      }
      if (text.getIndex() == text.getEndIndex()) {
        text.setIndex(sentenceStarts[currentSentence]);
      } else {
        text.setIndex(sentenceStarts[--currentSentence]);
      }
      return current();
    }
  }

  @Override
  public int preceding(int pos) {
    if (pos < text.getBeginIndex() || pos > text.getEndIndex()) {
      throw new IllegalArgumentException("offset out of bounds");
    } else if (0 == sentenceStarts.length) {
      text.setIndex(text.getBeginIndex());
      currentSentence = 0;
      return DONE;
    } else if (pos < sentenceStarts[0]) {
      text.setIndex(text.getBeginIndex());
      currentSentence = 0;
      return DONE;
    } else {
      currentSentence = (sentenceStarts.length - 1) / 2; // FIXED
      moveToSentenceAt(pos, 0, sentenceStarts.length - 1);
      if (0 == currentSentence) {
        text.setIndex(text.getBeginIndex());
        return DONE;
      } else {
        text.setIndex(sentenceStarts[--currentSentence]);
        return current();
      }
    }
  }

  @Override
  public int next(int n) {
    currentSentence += n;
    if (n < 0) {
      if (text.getIndex() == text.getEndIndex()) {
        ++currentSentence;
      }
      if (currentSentence < 0) {
        currentSentence = 0;
        text.setIndex(text.getBeginIndex());
        return DONE;
      } else {
        text.setIndex(sentenceStarts[currentSentence]);
      }
    } else if (n > 0) {
      if (currentSentence >= sentenceStarts.length) {
        currentSentence = sentenceStarts.length - 1;
        text.setIndex(text.getEndIndex());
        return DONE;
      } else {
        text.setIndex(sentenceStarts[currentSentence]);
      }
    }
    return current();
  }

  @Override
  public CharacterIterator getText() {
    return text;
  }

  @Override
  public void setText(CharacterIterator newText) {
    text = newText;
    text.setIndex(text.getBeginIndex());
    currentSentence = 0;
  }

  // ---- test harness ----
  public static void main(String[] args) {
    String text = "This is sentence one. This is sentence two.";
    int[] starts = {0, 22};

    FixedIterator bi = new FixedIterator(starts, text);
    int r = bi.preceding(25);
    if (r != 0) throw new AssertionError("preceding(25) expected 0 but got " + r);
    System.out.println("preceding(25) = " + r + " OK");

    for (int pos = 0; pos <= text.length(); pos++) {
      bi = new FixedIterator(starts, text);
      int res = bi.preceding(pos);
      System.out.println("preceding(" + pos + ") = " + res);
    }

    String text3 = "Sentence number 1 has 6 words. Sentence number 2, 5 words. And finally, sentence number 3 has 8 words.";
    int[] starts3 = {0, 31, 59};
    FixedIterator bi3 = new FixedIterator(starts3, text3);
    assertEquals(0, bi3.preceding(57));
    bi3 = new FixedIterator(starts3, text3);
    assertEquals(0, bi3.preceding(58));
    bi3 = new FixedIterator(starts3, text3);
    assertEquals(31, bi3.preceding(59));
    bi3 = new FixedIterator(starts3, text3);
    assertEquals(59, bi3.following(39));
    bi3 = new FixedIterator(starts3, text3);
    assertEquals(59, bi3.following(31));
    bi3 = new FixedIterator(starts3, text3);
    assertEquals(31, bi3.following(30));
    System.out.println("three-sentence scenarios OK");

    String text1 = "Sentence number 1 has 6 words. ";
    int[] starts1 = {0};
    FixedIterator bi1 = new FixedIterator(starts1, text1);
    assertEquals(BreakIterator.DONE, bi1.preceding(text1.length() / 2));
    bi1 = new FixedIterator(starts1, text1);
    assertEquals(BreakIterator.DONE, bi1.following(text1.length() / 2));
    System.out.println("single-sentence scenarios OK");

    FixedIterator bi0 = new FixedIterator(new int[0], "   ");
    assertEquals(BreakIterator.DONE, bi0.preceding(0));
    assertEquals(BreakIterator.DONE, bi0.following(0));
    System.out.println("zero-sentence scenarios OK");

    java.util.Random rnd = new java.util.Random(42);
    for (int trial = 0; trial < 2000; trial++) {
      int nSent = 1 + rnd.nextInt(5);
      StringBuilder sb = new StringBuilder();
      int[] st = new int[nSent];
      for (int i = 0; i < nSent; i++) {
        st[i] = sb.length();
        sb.append("Word ").append(i).append(". ");
      }
      String t = sb.toString();
      for (int pos = 0; pos <= t.length(); pos++) {
        FixedIterator b = new FixedIterator(st, t);
        b.preceding(pos); // must not throw
        b = new FixedIterator(st, t);
        b.following(pos); // must not throw
      }
    }
    System.out.println("fuzz OK");
    System.out.println("ALL TESTS PASSED");
  }

  static void assertEquals(int expected, int actual) {
    if (expected != actual) throw new AssertionError("expected " + expected + " got " + actual);
  }
}

